import{_ as t,o as a,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Keynote: Ceph: The Future of the Storage TODAY","description":"","frontmatter":{"title":"Keynote: Ceph: The Future of the Storage TODAY","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","IBM","Red Hat","开源"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Keynote_-_Ceph_-_The_Future_of_the_Storage_TODAY.md","filePath":"posts/2023/Keynote_-_Ceph_-_The_Future_of_the_Storage_TODAY.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Keynote_-_Ceph_-_The_Future_of_the_Storage_TODAY.md"};function i(h,e,_,p,n,s){return a(),l("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>在Cephalicon会议上，IBM的Danny Mace介绍了IBM与Red Hat在Ceph项目上的合作及未来计划。Kyle参与了讨论，分享了IBM对Ceph社区的贡献和未来发展方向。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>IBM与Red Hat的合作</strong>：</p><ul><li>IBM接手了Red Hat的Ceph团队工程师，以加强软件定义存储能力。</li><li>IBM和Red Hat认为这一合作对Ceph和相关开源项目的发展有益。</li></ul></li><li><p><strong>IBM的存储业务战略</strong>：</p><ul><li>IBM在存储业务中同时拥有硬件和软件，致力于发展软件定义存储业务。</li><li>IBM是全球最大的Kubernetes软件供应商，专注于混合云和OpenShift平台。</li></ul></li><li><p><strong>Ceph的未来发展</strong>：</p><ul><li>IBM计划扩展Ceph的应用场景，包括容器存储、混合云环境和新用例。</li><li>IBM承诺Ceph将继续保持100%开源，并优先考虑上游开发。</li></ul></li><li><p><strong>Ceph的社区和生态系统</strong>：</p><ul><li>Ceph拥有15年的发展历史和活跃的社区，IBM希望通过增加贡献来进一步增强其生态系统。</li><li>IBM计划通过提供最佳的S3、NFS和NVMe over TCP接口来扩展Ceph的市场。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>IBM和Red Hat已正式将Ceph团队从Red Hat转移到IBM，工程师团队保持完整。</li><li>IBM承诺Ceph将继续保持100%开源，并优先考虑上游开发。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li>IBM将扩展对Ceph的贡献，特别是在容器存储、混合云环境和新的存储用例方面。</li><li>IBM将加强Ceph的生态系统，提供最佳的S3、NFS和NVMe over TCP接口，以进入新的市场和应用领域。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>IBM对Ceph的未来充满信心，并计划通过增强其功能和扩展其应用场景来推动Ceph的发展。IBM承诺将继续支持Ceph的开源性质，并通过其全球销售网络来推广Ceph。</p>',11)])])}const C=t(r,[["render",i]]);export{d as __pageData,C as default};
